-- TaxGabay: the whole database in one file (Supabase → SQL Editor → paste → Run).
-- GENERATED by `pnpm db:setup-sql` from supabase/migrations, seed.sql and seed-issuances.sql. Run it once, on a new project.

-- ======================================================================
-- supabase/migrations/20261122000000_initial_schema.sql
-- ======================================================================
-- TaxGabay initial schema (Phase 1).
-- Reference data: public read, admin write, every change audited.
-- User data: Row Level Security, owner-only.

create extension if not exists pgcrypto;

-- ---------- Helpers ----------

create or replace function public.is_admin() returns boolean
language sql stable as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false);
$$;

create table public.admin_audit_log (
  id bigint generated always as identity primary key,
  table_name text not null,
  row_pk text not null,
  action text not null check (action in ('INSERT', 'UPDATE', 'DELETE')),
  old_row jsonb,
  new_row jsonb,
  actor uuid default auth.uid(),
  at timestamptz not null default now()
);

create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  pk text;
begin
  pk := coalesce(
    (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end) ->> 'id',
    (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end) ->> 'code',
    (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end) ->> 'date'
  );
  insert into public.admin_audit_log (table_name, row_pk, action, old_row, new_row)
  values (
    tg_table_name, coalesce(pk, '?'), tg_op,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end
  );
  return coalesce(new, old);
end;
$$;

-- ---------- Reference data ----------

create table public.tax_rules (
  id text primary key,
  rule_key text not null,
  tax_type text not null,
  taxpayer_category text not null,
  value_json jsonb not null,
  effective_from date not null,
  effective_to date,
  legal_basis text not null,
  source_url text,
  last_verified_at date,
  needs_verification boolean not null default true,
  note text,
  check (effective_to is null or effective_to >= effective_from)
);
create index tax_rules_lookup on public.tax_rules (rule_key, taxpayer_category, effective_from);

create table public.deadline_rules (
  id text primary key,
  form_code text not null,
  title text not null,
  frequency text not null check (frequency in ('monthly', 'quarterly', 'annual', 'one_time', 'event')),
  due_logic_json jsonb not null,
  applies_when_json jsonb not null,
  filing_channel text not null default 'all',
  effective_from date not null,
  effective_to date,
  legal_basis text not null,
  source_url text,
  last_verified_at date,
  needs_verification boolean not null default true,
  note text
);

create table public.holidays (
  date date primary key,
  name text not null,
  type text not null check (type in ('regular', 'special_non_working')),
  year int not null,
  legal_basis text not null,
  needs_verification boolean not null default true,
  note text
);

create table public.deadline_extensions (
  id uuid primary key default gen_random_uuid(),
  form_code text not null,
  original_date date not null,
  new_date date not null,
  issuance_ref text not null
);

create table public.forms (
  code text primary key,
  name text not null,
  description text not null,
  who_files text not null,
  frequency text not null,
  attachments_json jsonb not null default '[]',
  filing_channels text[] not null default '{}',
  guide_slug text,
  needs_verification boolean not null default true
);

create table public.issuances (
  id uuid primary key default gen_random_uuid(),
  type text not null check (type in ('RR', 'RMO', 'RMC', 'RAMO', 'BIR Ruling', 'DOF Order', 'RA', 'EO', 'CTA/SC decision', 'SEC', 'LGU')),
  number text not null,
  title text not null,
  date_issued date,
  effectivity_date date,
  tax_types text[] not null default '{}',
  topics text[] not null default '{}',
  summary_plain text,
  status text not null default 'active' check (status in ('active', 'amended', 'revoked', 'superseded')),
  workflow_state text not null default 'draft' check (workflow_state in ('draft', 'reviewed', 'published')),
  source_url text,
  pdf_path text,
  added_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz,
  search tsvector generated always as (
    to_tsvector('english', coalesce(number, '') || ' ' || coalesce(title, '') || ' ' || coalesce(summary_plain, ''))
  ) stored,
  unique (type, number)
);
create index issuances_search on public.issuances using gin (search);

create table public.issuance_links (
  from_id uuid not null references public.issuances (id) on delete cascade,
  to_id uuid not null references public.issuances (id) on delete cascade,
  relation text not null check (relation in ('amends', 'revokes', 'implements', 'clarifies')),
  primary key (from_id, to_id, relation)
);

create table public.registration_steps (
  id text primary key,
  business_form text not null check (business_form in ('dti', 'sec', 'cda')),
  "order" int not null,
  agency text not null,
  title text not null,
  summary text not null,
  requirements_json jsonb not null default '[]',
  "where" text,
  online_link text,
  fees_note text,
  est_days text,
  legal_basis text not null,
  only_if_employees boolean not null default false,
  needs_verification boolean not null default true
);

create table public.checklist_templates (
  id text primary key,
  title text not null,
  frequency text not null check (frequency in ('monthly', 'quarterly', 'annual', 'one_time'))
);

create table public.checklist_items (
  id text primary key,
  template_id text not null references public.checklist_templates (id) on delete cascade,
  title text not null,
  frequency text not null,
  applies_when_json jsonb not null default '{}',
  form_code text references public.forms (code)
);

-- ---------- User data ----------

create table public.profiles (
  user_id uuid primary key references auth.users (id) on delete cascade,
  taxpayer_type text not null,
  business_form text,
  vat_status text not null,
  income_tax_option text not null,
  has_employees boolean not null default false,
  withholds_expanded boolean not null default false,
  filing_channel text not null,
  efps_group text check (efps_group in ('A', 'B', 'C', 'D', 'E')),
  fiscal_year_end_month int not null default 12 check (fiscal_year_end_month between 1 and 12),
  rdo_code text,
  taxpayer_size text not null,
  line_of_business text,
  consent_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.user_obligations (
  user_id uuid not null references auth.users (id) on delete cascade,
  obligation_id text not null, -- "<deadline_rule_id>:<period_end>"
  deadline_rule_id text not null references public.deadline_rules (id),
  period text not null,
  due_date date not null,
  status text not null default 'pending' check (status in ('pending', 'filed', 'paid', 'filed_and_paid')),
  completed_at timestamptz,
  primary key (user_id, obligation_id)
);

create table public.user_roadmap_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  step_id text not null references public.registration_steps (id),
  done_at timestamptz not null default now(),
  primary key (user_id, step_id)
);

create table public.user_checklist_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  checklist_item_id text not null references public.checklist_items (id),
  period text not null,
  done_at timestamptz not null default now(),
  primary key (user_id, checklist_item_id, period)
);

create table public.saved_calculations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  calculator text not null,
  input_json jsonb not null,
  result_json jsonb not null,
  created_at timestamptz not null default now()
);

create table public.reminder_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  days_before int[] not null default '{7,3,1}',
  email_enabled boolean not null default true,
  push_enabled boolean not null default false
);

create table public.bookmarks (
  user_id uuid not null references auth.users (id) on delete cascade,
  target_type text not null,
  target_id text not null,
  created_at timestamptz not null default now(),
  primary key (user_id, target_type, target_id)
);

-- ---------- RLS: reference tables (public read, admin write) ----------

do $$
declare t text;
begin
  foreach t in array array['tax_rules', 'deadline_rules', 'holidays', 'deadline_extensions', 'forms',
                           'issuance_links', 'registration_steps', 'checklist_templates', 'checklist_items']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "%s: public read" on public.%I for select using (true)', t, t);
    execute format('create policy "%s: admin write" on public.%I for all using (public.is_admin()) with check (public.is_admin())', t, t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()', t || '_audit', t);
  end loop;
end $$;

-- Issuances: only published rows are public.
alter table public.issuances enable row level security;
create policy "issuances: public read published" on public.issuances for select using (workflow_state = 'published' or public.is_admin());
create policy "issuances: admin write" on public.issuances for all using (public.is_admin()) with check (public.is_admin());
create trigger issuances_audit after insert or update or delete on public.issuances for each row execute function public.audit_row();

alter table public.admin_audit_log enable row level security;
create policy "audit: admin read" on public.admin_audit_log for select using (public.is_admin());

-- ---------- RLS: user tables (owner only) ----------

do $$
declare t text;
begin
  foreach t in array array['profiles', 'user_obligations', 'user_roadmap_progress', 'user_checklist_progress',
                           'saved_calculations', 'reminder_settings', 'bookmarks']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "%s: owner" on public.%I for all using (auth.uid() = user_id) with check (auth.uid() = user_id)', t, t);
  end loop;
end $$;

-- ---------- Account deletion (RA 10173) ----------

create or replace function public.delete_my_account() returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  delete from auth.users where id = auth.uid(); -- user tables cascade
end;
$$;
revoke all on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;

-- ======================================================================
-- supabase/migrations/20261123000000_phase2.sql
-- ======================================================================
-- Phase 2: checklist item details, reminders (push subscriptions, send log).

alter table public.checklist_items
  add column detail text,
  add column months text check (months in ('non_quarter_end', 'quarter_end')),
  add column quarters int[],
  add column due_hint text,
  add column legal_basis text,
  add column needs_verification boolean not null default true;

-- Web push subscriptions (one row per browser/device).
create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  created_at timestamptz not null default now()
);
alter table public.push_subscriptions enable row level security;
create policy "push_subscriptions: owner" on public.push_subscriptions
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Idempotency log for the reminder job (service role only; users can read their own).
create table public.reminder_log (
  user_id uuid not null references auth.users (id) on delete cascade,
  reminder_key text not null, -- "<obligation id>:<days before>"
  channel text not null check (channel in ('email', 'push')),
  sent_at timestamptz not null default now(),
  primary key (user_id, reminder_key, channel)
);
alter table public.reminder_log enable row level security;
create policy "reminder_log: owner read" on public.reminder_log for select using (auth.uid() = user_id);

-- ======================================================================
-- supabase/migrations/20261124000000_phase3_issuances.sql
-- ======================================================================
-- Phase 3: issuance library workflow (draft → reviewed → published), enforced in the database.

alter table public.issuances
  add column slug text,
  add column reviewed_by uuid references auth.users (id) on delete set null,
  add column needs_verification boolean not null default true,
  add column updated_at timestamptz not null default now();

update public.issuances
  set slug = lower(regexp_replace(
    case type when 'BIR Ruling' then 'bir-ruling' when 'DOF Order' then 'dof-order' when 'CTA/SC decision' then 'court' else type end
    || '-' || number, '[^A-Za-z0-9]+', '-', 'g'));
alter table public.issuances alter column slug set not null;
create unique index issuances_slug on public.issuances (slug);

create or replace function public.issuance_workflow() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  content_changed boolean;
begin
  if tg_op = 'INSERT' then
    if new.workflow_state <> 'draft' then
      raise exception 'New issuances must start as drafts';
    end if;
    new.added_by := coalesce(new.added_by, auth.uid());
    new.reviewed_at := null;
    new.reviewed_by := null;
    return new;
  end if;

  new.updated_at := now();
  content_changed := (to_jsonb(new) - array['workflow_state', 'reviewed_at', 'reviewed_by', 'search', 'updated_at'])
                     is distinct from (to_jsonb(old) - array['workflow_state', 'reviewed_at', 'reviewed_by', 'search', 'updated_at']);

  if new.workflow_state is distinct from old.workflow_state then
    if content_changed then
      raise exception 'Save content changes and workflow changes separately';
    end if;
    if not (
      (old.workflow_state = 'draft' and new.workflow_state = 'reviewed') or
      (old.workflow_state = 'reviewed' and new.workflow_state in ('published', 'draft')) or
      (old.workflow_state = 'published' and new.workflow_state = 'draft')
    ) then
      raise exception 'Cannot move an issuance from % to %', old.workflow_state, new.workflow_state;
    end if;
    if new.workflow_state = 'reviewed' then
      if coalesce(btrim(new.summary_plain), '') = '' or new.source_url is null or cardinality(new.tax_types) = 0 then
        raise exception 'A summary, the official source link and at least one tax type are required before review';
      end if;
      new.reviewed_at := now();
      new.reviewed_by := auth.uid();
    elsif new.workflow_state = 'draft' then
      new.reviewed_at := null;
      new.reviewed_by := null;
    end if;
  elsif content_changed and old.workflow_state <> 'draft' then
    -- Editing a reviewed or published issuance sends it back for review.
    new.workflow_state := 'draft';
    new.reviewed_at := null;
    new.reviewed_by := null;
  end if;
  return new;
end;
$$;

create trigger issuances_workflow before insert or update on public.issuances
  for each row execute function public.issuance_workflow();

-- Links are public only when both ends are published.
drop policy "issuance_links: public read" on public.issuance_links;
create policy "issuance_links: public read published" on public.issuance_links for select using (
  public.is_admin() or (
    exists (select 1 from public.issuances i where i.id = from_id and i.workflow_state = 'published') and
    exists (select 1 from public.issuances i where i.id = to_id and i.workflow_state = 'published')
  )
);

create index issuances_tax_types on public.issuances using gin (tax_types);
create index issuances_topics on public.issuances using gin (topics);

-- ======================================================================
-- supabase/migrations/20261125000000_phase4_clients.sql
-- ======================================================================
-- Phase 4: multi-client mode (bookkeepers).
--
-- A user can keep several taxpayer profiles ("clients"). Rows with client_id = NULL
-- belong to the user's default client — every row written before this migration is
-- therefore the default client's, and nothing needs to be moved.

create table public.clients (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (length(btrim(name)) between 1 and 120),
  created_at timestamptz not null default now()
);
create index clients_user on public.clients (user_id);
alter table public.clients enable row level security;
create policy "clients: owner" on public.clients for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Is this client one of the current user's (or the default client)?
create or replace function public.owns_client(cid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select cid is null or exists (select 1 from public.clients c where c.id = cid and c.user_id = auth.uid());
$$;

-- profiles: one row per (user, client).
alter table public.profiles drop constraint profiles_pkey;
alter table public.profiles add column id uuid not null default gen_random_uuid() primary key;
alter table public.profiles add column client_id uuid references public.clients (id) on delete cascade;
alter table public.profiles add constraint profiles_user_client unique nulls not distinct (user_id, client_id);

-- user_obligations: one row per (user, client, obligation).
alter table public.user_obligations drop constraint user_obligations_pkey;
alter table public.user_obligations add column id uuid not null default gen_random_uuid() primary key;
alter table public.user_obligations add column client_id uuid references public.clients (id) on delete cascade;
alter table public.user_obligations add constraint user_obligations_user_client_obligation unique nulls not distinct (user_id, client_id, obligation_id);

-- user_roadmap_progress: one row per (user, client, step).
alter table public.user_roadmap_progress drop constraint user_roadmap_progress_pkey;
alter table public.user_roadmap_progress add column id uuid not null default gen_random_uuid() primary key;
alter table public.user_roadmap_progress add column client_id uuid references public.clients (id) on delete cascade;
alter table public.user_roadmap_progress add constraint user_roadmap_progress_user_client_step unique nulls not distinct (user_id, client_id, step_id);

-- user_checklist_progress: one row per (user, client, item, period).
alter table public.user_checklist_progress drop constraint user_checklist_progress_pkey;
alter table public.user_checklist_progress add column id uuid not null default gen_random_uuid() primary key;
alter table public.user_checklist_progress add column client_id uuid references public.clients (id) on delete cascade;
alter table public.user_checklist_progress add constraint user_checklist_progress_user_client_item unique nulls not distinct (user_id, client_id, checklist_item_id, period);

-- Owner policies now also require that a referenced client belongs to the same user,
-- so nobody can attach rows to another user's client id.
do $$
declare t text;
begin
  foreach t in array array['profiles', 'user_obligations', 'user_roadmap_progress', 'user_checklist_progress']
  loop
    execute format('drop policy "%s: owner" on public.%I', t, t);
    execute format(
      'create policy "%s: owner" on public.%I for all using (auth.uid() = user_id) with check (auth.uid() = user_id and public.owns_client(client_id))',
      t, t);
  end loop;
end $$;

-- ======================================================================
-- supabase/migrations/20261126000000_phase6_preparation.sql
-- ======================================================================
-- Phase 6: client records in, prepared documents out.
--
-- One firm (Neil Priolo, CPA's). Firm members (preparer, reviewer, admin) see every
-- client of the firm. Client users see only the client(s) they are linked to: they
-- enter records and receipts, and receive packets once the firm releases them.
-- TaxGabay prepares documents; it never files or pays.
--
-- TINs are stored encrypted (pgcrypto, pgp_sym_encrypt) and only after the client has
-- given TIN consent. The key never lives in a table:
--   * Supabase (production): a Vault secret named 'tin_key'
--       select vault.create_secret('<long random key>', 'tin_key');
--   * Plain Postgres (local tests): a setting
--       set app.tin_key = '<key>';   (or alter database ... set app.tin_key = ...)
-- Plaintext TINs are only accepted and returned by the SECURITY DEFINER functions
-- set_tin / get_tin, which check firm membership or client access plus consent.

create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public;

-- ---------- Firm members ----------

create table public.firm_members (
  user_id uuid primary key references auth.users (id) on delete cascade,
  role text not null check (role in ('preparer', 'reviewer', 'admin')),
  display_name text,
  created_at timestamptz not null default now()
);

create or replace function public.firm_role() returns text
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select role from public.firm_members where user_id = auth.uid()),
    case when public.is_admin() then 'admin' end
  );
$$;

create or replace function public.is_firm_member() returns boolean
language sql stable security definer set search_path = public as $$
  select public.firm_role() is not null;
$$;

-- ---------- Clients of the firm ----------
-- Separate from public.clients (Phase 4), which are a bookkeeper's private, browser-style
-- profiles. A prep client is a real business the firm prepares documents for.

create table public.prep_clients (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 160),
  -- Taxpayer profile (same shape as tax-engine Profile), used to know which documents are due.
  profile jsonb not null default '{}'::jsonb,
  archived boolean not null default false,
  created_by uuid references auth.users (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);

create table public.client_users (
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (prep_client_id, user_id)
);
create index client_users_user on public.client_users (user_id);

create or replace function public.is_client_user(cid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.client_users cu where cu.prep_client_id = cid and cu.user_id = auth.uid());
$$;

create or replace function public.can_access_client(cid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_firm_member() or public.is_client_user(cid);
$$;

-- ---------- Consents (RA 10173) ----------

create table public.client_consents (
  id uuid primary key default gen_random_uuid(),
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  consent_type text not null check (consent_type in ('records_storage', 'tin')),
  version text not null,
  accepted_at timestamptz not null default now(),
  withdrawn_at timestamptz
);
create index client_consents_client on public.client_consents (prep_client_id, consent_type);

create or replace function public.has_consent(cid uuid, ctype text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.client_consents c
    where c.prep_client_id = cid and c.consent_type = ctype and c.withdrawn_at is null
  );
$$;

-- ---------- Periods ----------

create table public.periods (
  id uuid primary key default gen_random_uuid(),
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  kind text not null check (kind in ('month', 'quarter', 'year')),
  start_date date not null,
  end_date date not null check (end_date >= start_date),
  status text not null default 'records_incomplete'
    check (status in ('records_incomplete', 'ready', 'prepared', 'reviewed', 'released', 'filed')),
  updated_at timestamptz not null default now(),
  unique (prep_client_id, kind, start_date)
);

-- Clients may only mark records complete (records_incomplete <-> ready) and mark a
-- released period as filed. Everything else is the firm's.
create or replace function public.period_status_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if public.is_firm_member() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.status not in ('records_incomplete', 'ready') then
      raise exception 'clients cannot create a period with status %', new.status;
    end if;
    return new;
  end if;
  if new.prep_client_id <> old.prep_client_id or new.kind <> old.kind
     or new.start_date <> old.start_date or new.end_date <> old.end_date then
    raise exception 'clients cannot change the period itself';
  end if;
  if new.status is distinct from old.status and not (
       (old.status in ('records_incomplete', 'ready') and new.status in ('records_incomplete', 'ready'))
    or (old.status = 'released' and new.status = 'filed')
  ) then
    raise exception 'clients cannot change status from % to %', old.status, new.status;
  end if;
  return new;
end;
$$;
create trigger periods_status_guard before insert or update on public.periods
  for each row execute function public.period_status_guard();

-- A record date is locked for clients once a covering period is with the firm or done.
create or replace function public.record_locked(cid uuid, d date) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.periods p
    where p.prep_client_id = cid and d between p.start_date and p.end_date
      and p.status in ('prepared', 'reviewed', 'released', 'filed')
  );
$$;

-- ---------- Records ----------

create table public.records (
  id uuid primary key default gen_random_uuid(),
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  record_date date not null,
  kind text not null check (kind in ('sale', 'expense', 'purchase', 'form_2307_received', 'payroll', 'asset', 'bank_balance', 'other')),
  -- Typed by kind (see packages/filing record types). Never contains a TIN: TINs go in public.tins.
  data jsonb not null default '{}'::jsonb,
  attachment_path text,
  created_by uuid references auth.users (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index records_client_date on public.records (prep_client_id, record_date);

create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
create trigger records_touch before update on public.records for each row execute function public.touch_updated_at();

-- ---------- TINs (encrypted) ----------

create table public.tins (
  id uuid primary key default gen_random_uuid(),
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  subject text not null check (subject in ('client', 'supplier', 'customer', 'employee', 'payor')),
  -- Who the TIN belongs to within the client (supplier or employee name key); '' for the client itself.
  subject_ref text not null default '',
  tin_encrypted bytea not null,
  last4 text not null check (last4 ~ '^[0-9]{4}$'),
  updated_by uuid references auth.users (id) on delete set null default auth.uid(),
  updated_at timestamptz not null default now(),
  unique (prep_client_id, subject, subject_ref)
);
-- RLS on and no policies: the table is reachable only through the functions below.

create or replace function private.tin_key() returns text
language plpgsql stable security definer set search_path = public as $$
declare k text;
begin
  if to_regclass('vault.decrypted_secrets') is not null then
    execute 'select decrypted_secret from vault.decrypted_secrets where name = $1 limit 1' into k using 'tin_key';
  end if;
  k := coalesce(k, nullif(current_setting('app.tin_key', true), ''));
  if k is null or length(k) < 16 then
    raise exception 'TIN encryption key is not configured';
  end if;
  return k;
end;
$$;
revoke all on function private.tin_key() from public;

create or replace function private.tin_guard(cid uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null or not public.can_access_client(cid) then
    raise exception 'not allowed';
  end if;
  if not public.has_consent(cid, 'tin') then
    raise exception 'TIN consent has not been given for this client';
  end if;
end;
$$;
revoke all on function private.tin_guard(uuid) from public;

create or replace function public.set_tin(cid uuid, subj text, ref text, tin text) returns void
language plpgsql security definer set search_path = public as $$
declare digits text := regexp_replace(coalesce(tin, ''), '[^0-9]', '', 'g');
begin
  perform private.tin_guard(cid);
  if length(digits) not between 9 and 14 then
    raise exception 'A TIN has 9 to 14 digits';
  end if;
  insert into public.tins (prep_client_id, subject, subject_ref, tin_encrypted, last4)
  values (cid, subj, coalesce(ref, ''), pgp_sym_encrypt(digits, private.tin_key()), right(digits, 4))
  on conflict (prep_client_id, subject, subject_ref) do update
    set tin_encrypted = excluded.tin_encrypted, last4 = excluded.last4, updated_by = auth.uid(), updated_at = now();
  insert into public.admin_audit_log (table_name, row_pk, action, new_row)
  values ('tins', cid::text || ':' || subj || ':' || coalesce(ref, ''), 'UPDATE', jsonb_build_object('last4', right(digits, 4)));
end;
$$;

create or replace function public.get_tin(cid uuid, subj text, ref text) returns text
language plpgsql security definer set search_path = public as $$
declare enc bytea;
begin
  perform private.tin_guard(cid);
  select tin_encrypted into enc from public.tins where prep_client_id = cid and subject = subj and subject_ref = coalesce(ref, '');
  if enc is null then
    return null;
  end if;
  return pgp_sym_decrypt(enc, private.tin_key());
end;
$$;

-- Masked list (last 4 digits), for showing which TINs are on file.
create or replace function public.list_tins(cid uuid) returns table (subject text, subject_ref text, last4 text, updated_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  perform private.tin_guard(cid);
  return query select t.subject, t.subject_ref, t.last4, t.updated_at from public.tins t where t.prep_client_id = cid order by 1, 2;
end;
$$;

create or replace function public.delete_tin(cid uuid, subj text, ref text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or not public.can_access_client(cid) then
    raise exception 'not allowed';
  end if;
  delete from public.tins where prep_client_id = cid and subject = subj and subject_ref = coalesce(ref, '');
end;
$$;

-- Withdrawing TIN consent erases the client's TINs.
create or replace function public.consent_withdrawn() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.consent_type = 'tin' and new.withdrawn_at is not null and old.withdrawn_at is null
     and not public.has_consent(new.prep_client_id, 'tin') then
    delete from public.tins where prep_client_id = new.prep_client_id;
  end if;
  return new;
end;
$$;
create trigger client_consents_withdrawn after update on public.client_consents
  for each row execute function public.consent_withdrawn();

revoke all on function public.set_tin(uuid, text, text, text), public.get_tin(uuid, text, text),
  public.list_tins(uuid), public.delete_tin(uuid, text, text) from public;
grant execute on function public.set_tin(uuid, text, text, text), public.get_tin(uuid, text, text),
  public.list_tins(uuid), public.delete_tin(uuid, text, text) to authenticated;

-- ---------- Packets (prepared documents) ----------

create table public.packets (
  id uuid primary key default gen_random_uuid(),
  period_id uuid not null references public.periods (id) on delete cascade,
  prep_client_id uuid not null references public.prep_clients (id) on delete cascade,
  -- Prepared documents with values, steps and warnings (packages/filing output).
  -- Never put TINs in the payload (it is copied to the audit log): fetch them with get_tin
  -- when rendering the PDF.
  payload jsonb not null,
  status text not null default 'prepared' check (status in ('prepared', 'reviewed', 'released')),
  prepared_by uuid references auth.users (id) on delete set null default auth.uid(),
  prepared_at timestamptz not null default now(),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz,
  released_at timestamptz,
  watermark text generated always as (case when status = 'prepared' then 'Draft — not reviewed' end) stored
);
create index packets_period on public.packets (period_id);

-- Review needs a reviewer or admin; release needs a reviewed packet. Reviewer and
-- timestamps are set here, not by the caller.
create or replace function public.packet_workflow() returns trigger
language plpgsql security definer set search_path = public as $$
declare r text := public.firm_role();
begin
  if r is null then
    raise exception 'only the firm can prepare, review or release packets';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'prepared' then
      raise exception 'a new packet starts as prepared';
    end if;
    new.prepared_by := auth.uid();
    new.prepared_at := now();
    new.reviewed_by := null; new.reviewed_at := null; new.released_at := null;
    return new;
  end if;
  if new.payload is distinct from old.payload and old.status <> 'prepared' then
    raise exception 'a reviewed or released packet cannot be changed; prepare a new one';
  end if;
  if new.status = old.status then
    return new;
  end if;
  if new.status = 'reviewed' then
    if old.status <> 'prepared' or r not in ('reviewer', 'admin') then
      raise exception 'only a reviewer can review a prepared packet';
    end if;
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  elsif new.status = 'released' then
    if old.status <> 'reviewed' then
      raise exception 'a packet must be reviewed before it is released';
    end if;
    new.released_at := now();
  elsif new.status = 'prepared' then
    if old.status = 'released' then
      raise exception 'a released packet cannot be withdrawn; prepare a new one';
    end if;
    new.reviewed_by := null; new.reviewed_at := null;
  end if;
  return new;
end;
$$;
create trigger packets_workflow before insert or update on public.packets
  for each row execute function public.packet_workflow();
create trigger packets_audit after insert or update or delete on public.packets
  for each row execute function public.audit_row();
create trigger periods_audit after update or delete on public.periods
  for each row execute function public.audit_row();

-- ---------- Row Level Security ----------

alter table public.firm_members enable row level security;
alter table public.prep_clients enable row level security;
alter table public.client_users enable row level security;
alter table public.client_consents enable row level security;
alter table public.periods enable row level security;
alter table public.records enable row level security;
alter table public.tins enable row level security;
alter table public.packets enable row level security;

create policy "firm_members: firm read" on public.firm_members for select using (public.is_firm_member());
create policy "firm_members: admin write" on public.firm_members for all
  using (public.firm_role() = 'admin') with check (public.firm_role() = 'admin');

create policy "prep_clients: read" on public.prep_clients for select using (public.can_access_client(id));
create policy "prep_clients: firm write" on public.prep_clients for all using (public.is_firm_member()) with check (public.is_firm_member());

create policy "client_users: read" on public.client_users for select using (public.is_firm_member() or user_id = auth.uid());
create policy "client_users: firm write" on public.client_users for all using (public.is_firm_member()) with check (public.is_firm_member());

create policy "client_consents: read" on public.client_consents for select using (public.can_access_client(prep_client_id));
create policy "client_consents: client gives" on public.client_consents for insert
  with check (user_id = auth.uid() and public.is_client_user(prep_client_id));
create policy "client_consents: client withdraws" on public.client_consents for update
  using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_client_user(prep_client_id));

create policy "periods: read" on public.periods for select using (public.can_access_client(prep_client_id));
create policy "periods: write" on public.periods for insert with check (public.can_access_client(prep_client_id));
create policy "periods: update" on public.periods for update
  using (public.can_access_client(prep_client_id)) with check (public.can_access_client(prep_client_id));
create policy "periods: firm delete" on public.periods for delete using (public.is_firm_member());

-- Clients add and edit their own records (after consenting to storage) while the period is open.
create policy "records: read" on public.records for select using (public.can_access_client(prep_client_id));
create policy "records: firm write" on public.records for all using (public.is_firm_member()) with check (public.is_firm_member());
create policy "records: client insert" on public.records for insert with check (
  public.is_client_user(prep_client_id) and public.has_consent(prep_client_id, 'records_storage')
  and not public.record_locked(prep_client_id, record_date));
create policy "records: client update" on public.records for update
  using (public.is_client_user(prep_client_id) and not public.record_locked(prep_client_id, record_date))
  with check (public.is_client_user(prep_client_id) and not public.record_locked(prep_client_id, record_date));
create policy "records: client delete" on public.records for delete
  using (public.is_client_user(prep_client_id) and not public.record_locked(prep_client_id, record_date));

-- Clients see a packet only once it is released; the firm sees all and writes (the trigger enforces roles).
create policy "packets: firm all" on public.packets for all using (public.is_firm_member()) with check (public.is_firm_member());
create policy "packets: client read released" on public.packets for select
  using (status = 'released' and public.is_client_user(prep_client_id));

-- The firm's admins can read the audit trail of packets, periods and TIN changes.
create policy "audit: firm admin read phase6" on public.admin_audit_log for select
  using (public.firm_role() = 'admin' and table_name in ('packets', 'periods', 'tins'));

-- ---------- Receipts storage ----------

create or replace function public.try_uuid(t text) returns uuid
language plpgsql immutable as $$
begin
  return t::uuid;
exception when others then
  return null;
end;
$$;
-- Private bucket; objects live under '<prep_client_id>/...'.

do $$
begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public) values ('receipts', 'receipts', false) on conflict (id) do nothing;
    execute $p$create policy "receipts: read" on storage.objects for select
      using (bucket_id = 'receipts' and public.can_access_client(public.try_uuid((storage.foldername(name))[1])))$p$;
    execute $p$create policy "receipts: upload" on storage.objects for insert
      with check (bucket_id = 'receipts' and public.can_access_client(public.try_uuid((storage.foldername(name))[1]))
        and (public.is_firm_member() or public.has_consent(public.try_uuid((storage.foldername(name))[1]), 'records_storage')))$p$;
    execute $p$create policy "receipts: delete" on storage.objects for delete
      using (bucket_id = 'receipts' and public.can_access_client(public.try_uuid((storage.foldername(name))[1])))$p$;
  end if;
end $$;

-- ======================================================================
-- supabase/migrations/20261127000000_phase6_invites.sql
-- ======================================================================
-- Phase 6: invite codes. The firm creates a client and gives the code to the client, who
-- enters it once after signing in; that links their account to the business.

create or replace function private.new_invite_code() returns text
language sql volatile as $$
  -- 10 characters from an alphabet without look-alikes (no 0/O, 1/I/L).
  select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + floor(random() * 31)::int, 1), '')
  from generate_series(1, 10);
$$;

alter table public.prep_clients
  add column invite_code text unique default private.new_invite_code();

-- Clients can read their client row (existing policy) but must not learn other codes;
-- the code is only useful before linking, so exposing it to linked users is harmless.

create or replace function public.claim_client(code text) returns uuid
language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  select id into cid from public.prep_clients
  where invite_code = upper(regexp_replace(coalesce(code, ''), '[^A-Za-z0-9]', '', 'g')) and not archived;
  if cid is null then
    raise exception 'That invite code is not valid. Check it with your CPA.';
  end if;
  insert into public.client_users (prep_client_id, user_id) values (cid, auth.uid())
  on conflict do nothing;
  return cid;
end;
$$;

-- The firm can issue a fresh code (for example after a client's staff member leaves).
create or replace function public.reset_invite_code(cid uuid) returns text
language plpgsql security definer set search_path = public as $$
declare c text := private.new_invite_code();
begin
  if not public.is_firm_member() then
    raise exception 'only the firm can reset invite codes';
  end if;
  update public.prep_clients set invite_code = c where id = cid;
  return c;
end;
$$;

revoke execute on function public.claim_client(text) from public, anon;
revoke execute on function public.reset_invite_code(uuid) from public, anon;
grant execute on function public.claim_client(text) to authenticated;
grant execute on function public.reset_invite_code(uuid) to authenticated;

-- ======================================================================
-- supabase/migrations/20261128000000_phase6_hardening.sql
-- ======================================================================
-- Phase 6 hardening.

-- 1. Receipts: only photos and PDFs, at most 10 MB, enforced by storage itself (not just the page),
--    so an HTML or SVG file cannot be uploaded and opened by the firm.
do $$
begin
  if to_regclass('storage.buckets') is not null
     and exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'buckets' and column_name = 'allowed_mime_types') then
    update storage.buckets
    set allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'],
        file_size_limit = 10485760
    where id = 'receipts';
  end if;
end $$;

-- 2. Only the firm's admins can delete a client (and with it every record, TIN and packet).
drop policy "prep_clients: firm write" on public.prep_clients;
create policy "prep_clients: firm insert" on public.prep_clients for insert with check (public.is_firm_member());
create policy "prep_clients: firm update" on public.prep_clients for update using (public.is_firm_member()) with check (public.is_firm_member());
create policy "prep_clients: admin delete" on public.prep_clients for delete using (public.firm_role() = 'admin');

-- 3. Invite codes: at most 10 wrong codes per account per hour.
create table private.claim_failures (
  user_id uuid not null,
  at timestamptz not null default now()
);
create index claim_failures_user_at on private.claim_failures (user_id, at);

create or replace function public.claim_client(code text) returns uuid
language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if (select count(*) from private.claim_failures where user_id = auth.uid() and at > now() - interval '1 hour') >= 10 then
    raise exception 'Too many wrong invite codes. Try again in an hour, or ask your CPA for the code.';
  end if;
  select id into cid from public.prep_clients
  where invite_code = upper(regexp_replace(coalesce(code, ''), '[^A-Za-z0-9]', '', 'g')) and not archived;
  if cid is null then
    -- Record the failure and return null (raising would roll the record back).
    insert into private.claim_failures (user_id) values (auth.uid());
    return null;
  end if;
  insert into public.client_users (prep_client_id, user_id) values (cid, auth.uid())
  on conflict do nothing;
  return cid;
end;
$$;
revoke execute on function public.claim_client(text) from public, anon;
grant execute on function public.claim_client(text) to authenticated;

