insert into public.registration_steps (id, business_form, "order", agency, title, summary, requirements_json, "where", online_link, fees_note, est_days, legal_basis, only_if_employees, needs_verification) values
  ('dti-bn', 'dti', 1, 'DTI', 'Register your business name with the DTI', 'A sole proprietorship uses a DTI-registered business name. Check availability and register online.', '["One valid government-issued ID","Proposed business name (with alternates)","Territorial scope (barangay, city/municipality, regional or national)"]'::jsonb, 'DTI Business Name Registration System (online) or a DTI Negosyo Center', 'https://bnrs.dti.gov.ph/', 'Fee depends on territorial scope (from about ₱200 for barangay to ₱2,000 for national) plus ₱30 documentary stamp tax. Registration is valid for 5 years.', 'Same day (online)', 'Act No. 3883 (Business Name Law), as amended; DTI Department Administrative Order on BNRS (number to confirm)', false, true),
  ('brgy', 'dti', 2, 'Barangay', 'Get a barangay business clearance', 'The barangay where your business operates issues a clearance needed for the mayor''s permit.', '["DTI business name certificate","Valid ID","Proof of business address (lease contract or land title/tax declaration)","Community tax certificate (cedula), if required"]'::jsonb, 'Barangay hall where the business is located', null, 'Set by barangay ordinance; varies.', '1–3 days', 'RA 7160 (Local Government Code) Sec. 152(c)', false, true),
  ('mayors-permit', 'dti', 3, 'City/Municipal Hall (BPLO)', 'Secure your mayor''s / business permit', 'Apply at the Business Permits and Licensing Office. Many LGUs have a one-stop business center or online portal.', '["Barangay clearance","DTI certificate","Proof of business address","Fire safety inspection, sanitary permit, zoning/locational clearance (as required by the LGU)"]'::jsonb, 'Business Permits and Licensing Office (BPLO) of the city or municipality', null, 'Local business tax and regulatory fees set by the LGU''s revenue code; based on capitalization for new businesses.', 'Up to 3 working days for simple transactions under the Ease of Doing Business Act (may be longer in practice)', 'RA 7160 Secs. 143 and 444; RA 11032 (Ease of Doing Business Act)', false, true),
  ('bir-1901', 'dti', 4, 'BIR', 'Register with the BIR (Form 1901) and get your COR', 'Register as a self-employed individual before you start operating. You will receive a Certificate of Registration (Form 2303) showing your tax types and filing obligations. Choose the 8% option here or in your first quarterly return if you qualify.', '["BIR Form 1901","Valid government-issued ID (and TIN if you already have one from employment)","DTI certificate","Mayor''s permit, or proof of application","Proof of business address"]'::jsonb, 'Online Registration and Update System (ORUS), or the RDO with jurisdiction over your business address', 'https://orus.bir.gov.ph/', 'The ₱500 annual registration fee was abolished by the Ease of Paying Taxes Act. Pay ₱30 documentary stamp tax where applicable (to confirm).', '1–3 days (varies by RDO)', 'NIRC Sec. 236, as amended by RA 11976 (EOPT); RR 7-2024 and RR 8-2024 (to confirm)', false, true),
  ('bir-books', 'dti', 5, 'BIR', 'Register your books of accounts', 'Register manual, loose-leaf or computerized books. Small taxpayers may keep simplified books.', '["Certificate of Registration (Form 2303)","Books to be registered (journal and ledger, or as allowed for your size)"]'::jsonb, 'ORUS or your RDO', 'https://orus.bir.gov.ph/', 'No BIR fee.', 'Same day to a few days', 'NIRC Sec. 232; RR 9-2009 (to confirm)', false, true),
  ('bir-invoices', 'dti', 6, 'BIR', 'Set up invoicing (Authority to Print or e-invoicing)', 'Under the Ease of Paying Taxes Act, the sales invoice is the primary document for both sales of goods and services (official receipts are now supplementary). Get an Authority to Print from an accredited printer or register your invoicing system.', '["Certificate of Registration (Form 2303)","Accredited printer''s ATP application, or registration of your computerized/e-invoicing system"]'::jsonb, 'ORUS / BIR accredited printer', 'https://orus.bir.gov.ph/', 'Printer charges vary.', 'Several days to weeks (printing)', 'NIRC Secs. 113 and 237, as amended by RA 11976 (EOPT); RR 7-2024', false, true),
  ('bir-posting', 'dti', 7, 'BIR', 'Post your COR and "Ask for an invoice" notice', 'Display your Certificate of Registration and the notice reminding customers to ask for an invoice at your place of business.', '["Certificate of Registration (Form 2303)","\"Ask for invoice\" notice (from BIR)"]'::jsonb, 'Your place of business, visible to customers', null, 'None.', 'Same day', 'NIRC Sec. 236; RR 7-2024 (to confirm)', false, true),
  ('employer-reg', 'dti', 8, 'SSS, PhilHealth, Pag-IBIG', 'Register as an employer (if you hire employees)', 'Register with SSS, PhilHealth and Pag-IBIG before or upon hiring, and report each employee.', '["DTI certificate and mayor''s permit","BIR COR","Employer registration forms (SSS R-1, PhilHealth ER1, Pag-IBIG Employer''s Data Form)","List of employees"]'::jsonb, 'Online portals or branches of each agency', 'https://www.sss.gov.ph/', 'No registration fee; monthly contributions apply.', '1–5 days per agency', 'RA 11199 (Social Security Act of 2018); RA 11223 (Universal Health Care Act); RA 9679 (HDMF Law of 2009)', true, true),
  ('sec-name', 'sec', 1, 'SEC', 'Verify and reserve your company name with the SEC', 'Check that the name is available and reserve it online before preparing your registration documents.', '["Proposed corporate or partnership name (with alternates)","SEC online account"]'::jsonb, 'SEC online registration system (eSPARC / the current SEC portal — to confirm)', 'https://www.sec.gov.ph/', 'Name reservation fee per SEC schedule (to confirm).', 'Same day (online)', 'RA 11232 (Revised Corporation Code) Sec. 17; SEC memorandum circulars on name verification (to confirm)', false, true),
  ('sec-register', 'sec', 2, 'SEC', 'File your articles and get your SEC Certificate of Incorporation/Registration', 'Submit the articles of incorporation (and by-laws for corporations other than OPCs) or articles of partnership, with the required undertakings. An OPC has a single stockholder and needs a nominee and alternate nominee.', '["Articles of incorporation / articles of partnership","By-laws (not required for an OPC)","OPC: written consent of the nominee and alternate nominee","Valid IDs and TINs of incorporators, directors/partners and officers","Treasurer''s certificate or proof of paid-up capital where required (to confirm)"]'::jsonb, 'SEC online registration system', 'https://www.sec.gov.ph/', 'Filing fees are based on authorized capital stock (or partnership capital) per the SEC fee schedule; plus legal research fee and documentary stamp tax.', 'About 1–3 working days after complete submission (to confirm)', 'RA 11232 (Revised Corporation Code) Secs. 13–18 and 115–132 (OPC); Civil Code Arts. 1767–1867 (partnerships)', false, true),
  ('sec-brgy', 'sec', 3, 'Barangay', 'Get a barangay business clearance', 'From the barangay where your principal office is located.', '["SEC certificate and articles","Proof of office address (lease contract or title)","Board/partners'' authorization for the representative"]'::jsonb, 'Barangay hall where the office is located', null, 'Set by barangay ordinance; varies.', '1–3 days', 'RA 7160 (Local Government Code) Sec. 152(c)', false, true),
  ('sec-mayors-permit', 'sec', 4, 'City/Municipal Hall (BPLO)', 'Secure your mayor''s / business permit', 'Apply at the Business Permits and Licensing Office or the LGU''s online business one-stop shop.', '["Barangay clearance","SEC certificate, articles and by-laws","Proof of office address","Fire safety inspection, sanitary permit and zoning clearance as required"]'::jsonb, 'Business Permits and Licensing Office (BPLO)', null, 'Local business tax and regulatory fees per the LGU revenue code.', 'Up to 3 working days for simple transactions under RA 11032 (may be longer in practice)', 'RA 7160 Secs. 143 and 444; RA 11032 (Ease of Doing Business Act)', false, true),
  ('sec-bir-1903', 'sec', 5, 'BIR', 'Register with the BIR (Form 1903), get your COR, register books and set up invoicing', 'Register the entity before it starts operating. You will get a Certificate of Registration (Form 2303) listing your tax types. Register your books of accounts and get an Authority to Print or register your invoicing system, then post your COR.', '["BIR Form 1903","SEC certificate, articles and by-laws","Mayor''s permit or proof of application","Board resolution/secretary''s certificate authorizing the representative","Proof of office address"]'::jsonb, 'ORUS, or the RDO with jurisdiction over the principal office', 'https://orus.bir.gov.ph/', 'The ₱500 annual registration fee was abolished by the Ease of Paying Taxes Act.', '1–3 days (varies by RDO)', 'NIRC Secs. 232, 236 and 237, as amended by RA 11976 (EOPT); RR 7-2024 and RR 8-2024 (to confirm)', false, true),
  ('sec-employer-reg', 'sec', 6, 'SSS, PhilHealth, Pag-IBIG', 'Register as an employer (if you hire employees)', 'Register with SSS, PhilHealth and Pag-IBIG before or upon hiring, and report each employee.', '["SEC certificate and mayor''s permit","BIR COR","Employer registration forms (SSS R-1, PhilHealth ER1, Pag-IBIG Employer''s Data Form)","List of employees"]'::jsonb, 'Online portals or branches of each agency', 'https://www.sss.gov.ph/', 'No registration fee; monthly contributions apply.', '1–5 days per agency', 'RA 11199; RA 11223; RA 9679', true, true),
  ('cda-pmes', 'cda', 1, 'CDA', 'Complete the Pre-Membership Education Seminar (PMES)', 'All prospective members attend the PMES on cooperative principles before organizing.', '["List of prospective members","PMES certificates"]'::jsonb, 'CDA extension office or accredited trainers', 'https://cda.gov.ph/', 'Varies by provider.', '1 day', 'RA 9520 (Philippine Cooperative Code of 2008) Art. 10', false, true),
  ('cda-name', 'cda', 2, 'CDA', 'Reserve the cooperative''s name with the CDA', 'Check that the proposed name is available and reserve it.', '["Proposed cooperative name","Name reservation form"]'::jsonb, 'CDA extension office or online', 'https://cda.gov.ph/', 'Name reservation fee per CDA schedule (to confirm).', 'Same day', 'RA 9520 Art. 16', false, true),
  ('cda-register', 'cda', 3, 'CDA', 'File for CDA registration and get your Certificate of Registration', 'Submit the articles of cooperation, by-laws and supporting documents. A primary cooperative needs at least 15 members and the minimum paid-up capital set by law.', '["Articles of cooperation and by-laws","Economic survey","Treasurer''s affidavit and proof of paid-up capital (at least ₱15,000 for primary cooperatives — to confirm)","Surety bond of accountable officers","PMES certificates of members"]'::jsonb, 'CDA extension office', 'https://cda.gov.ph/', 'Registration fee per CDA schedule (to confirm).', 'Up to 30 days under RA 9520 (to confirm)', 'RA 9520 Arts. 10–17', false, true),
  ('cda-permits', 'cda', 4, 'Barangay and City/Municipal Hall', 'Get barangay clearance and mayor''s/business permit', 'Cooperatives may be exempt from some local taxes but still need permits to operate.', '["CDA certificate of registration","Articles and by-laws","Proof of office address"]'::jsonb, 'Barangay hall and BPLO', null, 'Per LGU ordinance; local tax exemptions may apply under RA 9520 Art. 61 (to confirm).', '1–5 days', 'RA 7160 Secs. 152(c) and 444; RA 9520 Art. 61', false, true),
  ('cda-bir', 'cda', 5, 'BIR', 'Register with the BIR (Form 1903) and apply for a Certificate of Tax Exemption', 'Register the cooperative, get the COR, register books and set up invoicing. To enjoy tax exemptions under RA 9520, apply for a Certificate of Tax Exemption (CTE) from the BIR.', '["BIR Form 1903","CDA certificate of registration","Articles and by-laws","CTE application and supporting documents"]'::jsonb, 'ORUS or the RDO with jurisdiction', 'https://orus.bir.gov.ph/', 'No annual registration fee.', 'Registration 1–3 days; CTE processing varies', 'RA 9520 Arts. 60–61; Joint Rules and Regulations Implementing Arts. 60, 61 and 144 of RA 9520; RMO 76-2010 (to confirm)', false, true),
  ('cda-employer-reg', 'cda', 6, 'SSS, PhilHealth, Pag-IBIG', 'Register as an employer (if you hire employees)', 'Register with SSS, PhilHealth and Pag-IBIG before or upon hiring.', '["CDA certificate","BIR COR","Employer registration forms","List of employees"]'::jsonb, 'Online portals or branches of each agency', 'https://www.sss.gov.ph/', 'No registration fee; monthly contributions apply.', '1–5 days per agency', 'RA 11199; RA 11223; RA 9679', true, true)
