  ('m-books', 'monthly', 'Update your books of accounts', 'monthly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Record every sale and expense for the month in your registered books.', null, null, 'Throughout the month', 'NIRC Sec. 232', true),
  ('m-invoices', 'monthly', 'Check that every sale has an invoice', 'monthly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Under the Ease of Paying Taxes Act, issue a sales invoice for each sale of goods or services and keep your copies.', null, null, 'At each sale', 'NIRC Secs. 113 and 237, as amended by RA 11976', true),
  ('m-1601c', 'monthly', 'File and pay 1601C (tax withheld from employees)', 'monthly', '{"has_employees":true}'::jsonb, '1601C', 'Remit the tax you withheld from salaries this month.', null, null, '10th of next month (15 January for December)', 'NIRC Sec. 58(A); RR 2-98', true),
  ('m-contributions', 'monthly', 'Remit SSS, PhilHealth and Pag-IBIG contributions', 'monthly', '{"has_employees":true}'::jsonb, null, 'Pay employer and employee shares for the month.', null, null, 'Per each agency''s schedule', 'RA 11199; RA 11223; RA 9679', true),
  ('m-0619e', 'monthly', 'File and pay 0619E (expanded withholding)', 'monthly', '{"withholds_expanded":true}'::jsonb, '0619E', 'Remit expanded withholding tax for the month.', 'non_quarter_end', null, '10th of next month', 'NIRC Sec. 58(A); RR 11-2018', true),
  ('q-1701q', 'quarterly', 'File 1701Q (quarterly income tax)', 'quarterly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship"]}'::jsonb, '1701Q', 'Report cumulative income for the year to date and pay any tax due.', null, '{1,2,3}', '15 May, 15 Aug, 15 Nov', 'NIRC Sec. 74', true),
  ('q-1702q', 'quarterly', 'File 1702Q (quarterly corporate income tax)', 'quarterly', '{"taxpayer_types":["partnership","corporation","opc","cooperative"]}'::jsonb, '1702Q', 'For the first three quarters of your taxable year.', null, null, 'Within 60 days after the quarter', 'NIRC Sec. 77(B)', true),
  ('q-2551q', 'quarterly', 'File 2551Q (percentage tax)', 'quarterly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"],"vat_status":["non_vat"],"not":{"income_tax_options":["eight_percent"]}}'::jsonb, '2551Q', '3% of gross sales or receipts for the quarter.', null, null, '25 days after the quarter', 'NIRC Secs. 116 and 128', true),
  ('q-2550q', 'quarterly', 'File 2550Q (VAT) and the Summary List of Sales and Purchases', 'quarterly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"],"vat_status":["vat"]}'::jsonb, '2550Q', 'Output VAT less input VAT for the quarter.', null, null, '25 days after the quarter', 'NIRC Sec. 114', true),
  ('q-1601eq', 'quarterly', 'File 1601EQ with the Quarterly Alphalist of Payees', 'quarterly', '{"withholds_expanded":true}'::jsonb, '1601EQ', 'Quarterly summary and remittance of expanded withholding tax.', null, null, 'Last day of the month after the quarter', 'NIRC Sec. 58(A); RR 11-2018', true),
  ('q-2307-issue', 'quarterly', 'Give BIR Form 2307 to the suppliers you withheld from', 'quarterly', '{"withholds_expanded":true}'::jsonb, null, 'Your payees need these certificates to claim tax credits.', null, null, 'Within 20 days after the quarter (to confirm)', 'RR 2-98 Sec. 2.58(B), as amended', true),
  ('q-2307-collect', 'quarterly', 'Collect BIR Form 2307 from clients who withheld from you', 'quarterly', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Attach them to your quarterly income tax return to claim the credit.', null, null, 'Before you file your quarterly income tax return', 'RR 2-98 Sec. 2.58.3', true),
  ('a-itr-ind', 'annual', 'File your annual income tax return (1701 or 1701A) for last year', 'annual', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship"]}'::jsonb, '1701A', 'Use 1701A if you are purely self-employed on 8% or OSD; otherwise 1701.', null, null, '15 April', 'NIRC Sec. 51(C)(1)', true),
  ('a-itr-corp', 'annual', 'File your annual corporate income tax return (1702) with financial statements', 'annual', '{"taxpayer_types":["partnership","corporation","opc","cooperative"]}'::jsonb, '1702-RT', 'Attach the audited financial statements where required.', null, null, '15th day of the 4th month after year end', 'NIRC Sec. 77(B)', true),
  ('a-1604c', 'annual', 'File 1604C with the alphalist of employees', 'annual', '{"has_employees":true}'::jsonb, '1604C', 'Annual information return of tax withheld on compensation.', null, null, '31 January', 'NIRC Sec. 58(C)', true),
  ('a-2316', 'annual', 'Give each employee their BIR Form 2316', 'annual', '{"has_employees":true}'::jsonb, null, 'Certificate of compensation and tax withheld for last year.', null, null, '31 January (to confirm)', 'NIRC Sec. 83, as amended by RA 10963', true),
  ('a-1604e', 'annual', 'File 1604E with the alphalist of payees', 'annual', '{"withholds_expanded":true}'::jsonb, '1604E', 'Annual information return of expanded withholding.', null, null, '1 March', 'NIRC Sec. 58(C)', true),
  ('a-inventory', 'annual', 'Submit your year-end inventory list (if you sell goods)', 'annual', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'List of inventory as of the end of the taxable year.', null, null, 'Within 30 days after year end (to confirm)', 'RR 17-2013 (to confirm)', true),
  ('a-books-close', 'annual', 'Close and keep your books for last year', 'annual', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Bind loose-leaf books and keep records for the period required by law.', null, null, 'Early in the year', 'NIRC Secs. 232 and 235, as amended by RA 11976', true),
  ('a-mayors-permit', 'annual', 'Renew your mayor''s/business permit', 'annual', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Renew with your city or municipality and pay local business tax.', null, null, 'By 20 January (LGU deadline varies)', 'RA 7160 Sec. 167', true),
  ('o-post-cor', 'one_time', 'Display your Certificate of Registration and "Ask for an invoice" notice', 'one_time', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Post them where customers can see.', null, null, 'When you start operating', 'NIRC Sec. 236', true),
  ('o-books-register', 'one_time', 'Register your books of accounts', 'one_time', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'Before you use them.', null, null, 'Before you start operating', 'NIRC Sec. 232', true),
  ('o-invoices', 'one_time', 'Get an Authority to Print or register your invoicing system', 'one_time', '{"taxpayer_types":["self_employed","mixed_income","sole_proprietorship","partnership","corporation","opc","cooperative"]}'::jsonb, null, 'So you can issue BIR-registered invoices.', null, null, 'Before your first sale', 'NIRC Sec. 238; RR 7-2024', true),
